import re

SEARCH_ENGINES = {"google.com", "bing.com", "duckduckgo.com"}
SEARCH_ENGINE_PATTERN = re.compile(rf"https?://(?:www\.)(?:{ '|'.join(SEARCH_ENGINES)})")

def is_search_engine(url):
    return SEARCH_ENGINE_PATTERN.match(url) is not None

def expand_links(html):
    urls = re.findall('http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\(\),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+', html)
    for url in urls:
        if is_search_engine(url):
            html = html.replace(url, f'<a href="{url}">{url}</a>')
    return html
